import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  inOutEnvelope,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;

// Durations
const SCENE_1 = 160;
const SCENE_2 = 180;
const SCENE_3 = 220;
const SCENE_4 = 150;

const Background: React.FC = () => (
  <AbsoluteFill style={{ background: COLORS.bg }} />
);

// ─────────────────────────────────────────────────────────────
// Apify "gate"
// ─────────────────────────────────────────────────────────────
const ApifyGate: React.FC<{
  x: number;
  y: number;
  size: number;
  blocked?: boolean;
  blockProgress?: number;
  unlockProgress?: number;
  statusOverride?: string;
}> = ({ x, y, size, blocked, blockProgress = 0, unlockProgress = 0, statusOverride }) => {
  const frame = useCurrentFrame();
  const breathe = ambientDrift(frame, 2, 90, "gate-breathe");
  const blockedTint = `rgba(239,68,68,${0.6 * blockProgress * (1 - unlockProgress)})`;

  const statusLabel =
    statusOverride ??
    (unlockProgress > 0.4
      ? "200 OK"
      : blocked
      ? "402 Payment Required"
      : "Awaiting Auth");

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y + breathe,
        width: size,
        height: size * 1.35,
        transform: "translate(-50%, -50%)",
        background: COLORS.card,
        border: `2px solid ${COLORS.border}`,
        borderRadius: 24,
        padding: size * 0.08,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        gap: size * 0.04,
        boxShadow: `0 0 ${60 + 80 * unlockProgress}px ${
          unlockProgress > 0.3
            ? `rgba(248,102,6,${0.4 * unlockProgress})`
            : blockedTint
        }`,
        overflow: "hidden",
        fontFamily: "Inter, sans-serif",
      }}
    >
      <Img
        src={staticFile("assets/apify/Apify symbol colors.svg")}
        style={{
          width: size * 0.32,
          height: size * 0.32,
          marginTop: size * 0.04,
        }}
      />
      <div
        style={{
          fontFamily: "'GT Walsheim', Inter, sans-serif",
          fontWeight: 600,
          fontSize: size * 0.11,
          color: COLORS.text,
          letterSpacing: "-0.02em",
        }}
      >
        apify
      </div>

      <div
        style={{
          marginTop: size * 0.05,
          fontFamily: "monospace",
          fontSize: size * 0.045,
          color: COLORS.textSubtle,
          background: "rgba(255,255,255,0.04)",
          padding: `${size * 0.02}px ${size * 0.04}px`,
          borderRadius: 8,
          letterSpacing: "0.02em",
        }}
      >
        api.apify.com/run
      </div>

      <div
        style={{
          marginTop: size * 0.04,
          fontWeight: 600,
          fontSize: size * 0.04,
          padding: `${size * 0.018}px ${size * 0.05}px`,
          borderRadius: 999,
          background:
            unlockProgress > 0.4
              ? COLORS.orangeTint
              : blocked
              ? "rgba(239,68,68,0.14)"
              : "rgba(255,255,255,0.05)",
          color:
            unlockProgress > 0.4
              ? COLORS.orange
              : blocked
              ? "#EF4444"
              : COLORS.textMuted,
          border: `1px solid ${
            unlockProgress > 0.4
              ? COLORS.orange
              : blocked
              ? "rgba(239,68,68,0.4)"
              : COLORS.border
          }`,
          letterSpacing: "0.08em",
          textTransform: "uppercase",
          fontFamily: "monospace",
        }}
      >
        {statusLabel}
      </div>

      <div
        style={{
          position: "absolute",
          inset: 0,
          border: `2px solid ${blockedTint}`,
          borderRadius: 24,
          pointerEvents: "none",
        }}
      />
    </div>
  );
};

// ─────────────────────────────────────────────────────────────
// Agent
// ─────────────────────────────────────────────────────────────
const Agent: React.FC<{
  x: number;
  y: number;
  size: number;
  label: string;
  delay: number;
  shake?: number;
}> = ({ x, y, size, label, delay, shake = 0 }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const inP = springIn(frame, vfps, delay, "ELASTIC");
  const bob = ambientDrift(frame, 3, 70, `agent-${label}`);
  const shakeX = shake > 0 ? Math.sin(frame * 1.6) * 8 * shake : 0;

  return (
    <div
      style={{
        position: "absolute",
        left: x + shakeX,
        top: y + bob,
        transform: `translate(-50%, -50%) scale(${interpolate(
          inP,
          [0, 1],
          [0.6, 1]
        )})`,
        opacity: inP,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: size * 0.12,
        fontFamily: "Inter, sans-serif",
      }}
    >
      <div
        style={{
          width: size,
          height: size,
          borderRadius: size * 0.28,
          background: COLORS.card,
          border: `1.5px solid ${COLORS.border}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: `0 12px 32px rgba(0,0,0,0.5)`,
        }}
      >
        <svg
          width={size * 0.55}
          height={size * 0.55}
          viewBox="0 0 24 24"
          fill="none"
        >
          <rect
            x={3}
            y={6}
            width={18}
            height={13}
            rx={3}
            stroke={COLORS.textMuted}
            strokeWidth={1.6}
          />
          <circle cx={9} cy={12.5} r={1.6} fill={COLORS.orange} />
          <circle cx={15} cy={12.5} r={1.6} fill={COLORS.orange} />
          <path
            d="M12 2v4"
            stroke={COLORS.textMuted}
            strokeWidth={1.6}
            strokeLinecap="round"
          />
          <circle cx={12} cy={2} r={1.2} fill={COLORS.textMuted} />
        </svg>
      </div>
      <div
        style={{
          fontFamily: "monospace",
          fontSize: size * 0.16,
          color: COLORS.textMuted,
          letterSpacing: "0.04em",
        }}
      >
        {label}
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────
// SCENE 1 — Every agent needs data from the web
// ─────────────────────────────────────────────────────────────
const SceneSetup: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const envelope = inOutEnvelope(frame, vfps, SCENE_1 + TRANSITION);

  const titleIn = springIn(frame, vfps, 5, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 18, "LIQUID");
  const subIn = springIn(frame, vfps, 28, "GENTLE");
  const gateIn = springIn(frame, vfps, 30, "LIQUID");
  const statIn = springIn(frame, vfps, 50, "ELASTIC");

  const titleDrift = ambientDrift(frame, 2, 110, "title-1");
  const gateSize = width * 0.22;

  const agentsApproach = interpolate(frame, [40, 140], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Agents travel along the lower-right portion of the canvas,
  // bumped up slightly so they sit higher above the bottom edge.
  const agentY1 = height * 0.7;
  const agentY2 = height * 0.8;
  const agentY3 = height * 0.6;
  const agentStartX = -width * 0.12;
  const agentTargetX = width * 0.42;
  const agentX = interpolate(agentsApproach, [0, 1], [agentStartX, agentTargetX]);

  const countProgress = spring({
    frame: frame - 50,
    fps: vfps,
    config: SPRINGS.LIQUID,
  });
  const actorCount = Math.round(interpolate(countProgress, [0, 1], [0, 35000]));

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      {/* transparent */}

      <div
        style={{
          position: "absolute",
          left: "8%",
          top: `calc(10% + ${titleDrift}px)`,
          maxWidth: width * 0.55,
        }}
      >
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 600,
            fontSize: width * 0.054,
            color: COLORS.text,
            lineHeight: 1.06,
            letterSpacing: "-0.025em",
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [28, 0])}px)`,
          }}
        >
          Every agent needs{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `3px solid ${COLORS.orange}`,
              padding: "0 14px",
              borderRadius: 8,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            data from the web
          </span>
          .
        </div>

        <div
          style={{
            marginTop: width * 0.025,
            fontFamily: "Inter, sans-serif",
            fontWeight: 400,
            fontSize: width * 0.022,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.4,
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [16, 0])}px)`,
            maxWidth: width * 0.42,
          }}
        >
          And Apify has thousands of ready-to-run Actors waiting.
        </div>

        {/* Stat chip */}
        <div
          style={{
            marginTop: width * 0.035,
            display: "inline-flex",
            alignItems: "baseline",
            gap: 18,
            background: "rgba(255,255,255,0.04)",
            border: `1px solid ${COLORS.border}`,
            borderRadius: 16,
            padding: "20px 32px",
            opacity: statIn,
            transform: `translateY(${interpolate(statIn, [0, 1], [16, 0])}px)`,
            fontFamily: "Inter, sans-serif",
          }}
        >
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontWeight: 600,
              fontSize: width * 0.045,
              color: COLORS.orange,
              letterSpacing: "-0.02em",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {actorCount.toLocaleString("en-US")}+
          </div>
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontWeight: 400,
              fontSize: width * 0.018,
              color: COLORS.textMuted,
              letterSpacing: "0.02em",
            }}
          >
            Actors on the Apify Store
          </div>
        </div>
      </div>

      <div
        style={{
          opacity: gateIn,
          transform: `translateY(${interpolate(gateIn, [0, 1], [40, 0])}px)`,
        }}
      >
        <ApifyGate x={width * 0.78} y={height * 0.45} size={gateSize} />
      </div>

      <Agent
        x={agentX}
        y={agentY1}
        size={width * 0.075}
        label="agent_01"
        delay={45}
      />
      <Agent
        x={agentX - width * 0.07}
        y={agentY2}
        size={width * 0.065}
        label="agent_02"
        delay={58}
      />
      <Agent
        x={agentX - width * 0.05}
        y={agentY3}
        size={width * 0.06}
        label="agent_03"
        delay={70}
      />

      <svg
        style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
        viewBox={`0 0 ${width} ${height}`}
      >
        <path
          d={`M ${agentX + width * 0.04} ${agentY1} Q ${width * 0.6} ${
            height * 0.55
          } ${width * 0.7} ${height * 0.5}`}
          stroke={COLORS.orange}
          strokeWidth={3}
          strokeDasharray="6 14"
          fill="none"
          opacity={0.35 * agentsApproach}
        />
      </svg>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────────────────────
// SCENE 2 — Blocked
// ─────────────────────────────────────────────────────────────
const SceneBlocked: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const envelope = inOutEnvelope(frame, vfps, SCENE_2 + TRANSITION);

  const titleIn = springIn(frame, vfps, 5, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 16, "LIQUID");
  const gateIn = springIn(frame, vfps, 8, "LIQUID");

  const blockProgress = interpolate(frame, [30, 55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const xPunch = spring({
    frame: frame - 35,
    fps: vfps,
    config: SPRINGS.ELASTIC,
  });

  const shake = interpolate(frame, [55, 90, 160], [0, 1, 0.6], {
    extrapolateRight: "clamp",
  });

  const gateSize = width * 0.24;
  const gateX = width * 0.76;
  const gateY = height * 0.45;

  const titleDrift = ambientDrift(frame, 2, 100, "title-2");

  const blockers = [
    { label: "no account", delay: 70 },
    { label: "no API key", delay: 84 },
    { label: "no credit card", delay: 98 },
  ];

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif", opacity: envelope }}>
      {/* transparent */}

      <div
        style={{
          position: "absolute",
          left: "8%",
          top: `calc(11% + ${titleDrift}px)`,
          maxWidth: width * 0.5,
        }}
      >
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 600,
            fontSize: width * 0.054,
            color: COLORS.text,
            lineHeight: 1.06,
            letterSpacing: "-0.025em",
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [28, 0])}px)`,
          }}
        >
          But agents{" "}
          <span
            style={{
              background: "rgba(239,68,68,0.12)",
              borderBottom: `3px solid #EF4444`,
