          }}
        >
          No account. No API key. No credit card. The whole signup flow assumes a human is at the keyboard.
        </div>

        <div
          style={{
            marginTop: width * 0.035,
            display: "flex",
            flexDirection: "column",
            gap: 14,
            fontFamily: "Inter, sans-serif",
          }}
        >
          {blockers.map((b, i) => {
            const p = springIn(frame, vfps, b.delay, "ELASTIC");
            return (
              <div
                key={i}
                style={{
                  display: "inline-flex",
                  alignSelf: "flex-start",
                  alignItems: "center",
                  gap: 16,
                  background: "rgba(239,68,68,0.1)",
                  border: `1.5px solid rgba(239,68,68,0.4)`,
                  borderRadius: 14,
                  padding: "14px 24px",
                  opacity: p,
                  transform: `translateX(${interpolate(p, [0, 1], [-20, 0])}px)`,
                  fontFamily: "monospace",
                  fontSize: width * 0.017,
                  color: "#EF4444",
                  letterSpacing: "0.08em",
                  textTransform: "uppercase",
                }}
              >
                <svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                  <circle
                    cx={12}
                    cy={12}
                    r={9}
                    stroke="#EF4444"
                    strokeWidth={2}
                  />
                  <line
                    x1={7}
                    y1={17}
                    x2={17}
                    y2={7}
                    stroke="#EF4444"
                    strokeWidth={2.4}
                    strokeLinecap="round"
                  />
                </svg>
                {b.label}
              </div>
            );
          })}
        </div>
      </div>

      <div
        style={{
          opacity: gateIn,
          transform: `translateY(${interpolate(gateIn, [0, 1], [40, 0])}px)`,
        }}
      >
        <ApifyGate
          x={gateX}
          y={gateY}
          size={gateSize}
          blocked={blockProgress > 0.3}
          blockProgress={blockProgress}
        />
      </div>

      <div
        style={{
          position: "absolute",
          left: gateX,
          top: gateY,
          transform: `translate(-50%, -50%) scale(${interpolate(
            xPunch,
            [0, 1],
            [0, 1]
          )}) rotate(${interpolate(xPunch, [0, 1], [-25, 0])}deg)`,
          opacity: blockProgress,
          filter: `drop-shadow(0 0 40px rgba(239,68,68,${0.6 * blockProgress}))`,
