      >
        <svg width={gateSize * 0.7} height={gateSize * 0.7} viewBox="0 0 100 100">
          <circle
            cx={50}
            cy={50}
            r={42}
            fill="rgba(239,68,68,0.18)"
            stroke="#EF4444"
            strokeWidth={4}
          />
          <line
            x1={30}
            y1={30}
            x2={70}
            y2={70}
            stroke="#EF4444"
            strokeWidth={8}
            strokeLinecap="round"
          />
          <line
            x1={70}
            y1={30}
            x2={30}
            y2={70}
            stroke="#EF4444"
            strokeWidth={8}
            strokeLinecap="round"
