        y={height * 0.8}
        size={width * 0.065}
        label="agent_02"
        delay={5}
        shake={shake}
      />
      <Agent
        x={width * 0.46}
        y={height * 0.6}
        size={width * 0.06}
        label="agent_03"
        delay={10}
        shake={shake}
      />
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────────────────────
