  const coinOpacity = interpolate(coinAbsorb, [0, 1], [1, 0]);
  const coinRotate = interpolate(coinTravel, [0, 1], [0, 540]);
  const coinSize = width * 0.09;

  const unlockProgress = interpolate(frame, [170, 210], [0, 1], {
